#include <iostream>
#include <vector>
#include <string>
using namespace std;

vector<int> parent, sizes;

int findRoot(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

bool unite(int a, int b) {
    a = findRoot(a);
    b = findRoot(b);
    if (a == b) return false;
    if (sizes[a] < sizes[b]) swap(a, b);
    parent[b] = a;
    sizes[a] += sizes[b];
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long h;
    long long w;
    long long q;
    cin >> h >> w >> q;
    vector<vector<long long>> ops(q, vector<long long>(2));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> ops[i][j];
        }
    }

    int cells = (int)(h * w);
    parent.resize(cells);
    sizes.assign(cells, 1);
    for (int v = 0; v < cells; v++) parent[v] = v;
    vector<char> land(cells, 0);
    long long count = 0;
    int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
    for (size_t i = 0; i < ops.size(); i++) {
        int r = (int)ops[i][0] - 1, c = (int)ops[i][1] - 1;
        int p = r * (int)w + c;
        if (!land[p]) {
            land[p] = 1;
            count++;
            for (int d = 0; d < 4; d++) {
                int a = r + dr[d], b = c + dc[d];
                if (a >= 0 && a < h && b >= 0 && b < w && land[a * (int)w + b]) {
                    if (unite(p, a * (int)w + b)) count--;
                }
            }
        }
        cout << (i ? " " : "") << count;
    }
    cout << "\n";

    return 0;
}

