import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] parent;
    static int[] sizes;

    static int findRoot(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static boolean unite(int a, int b) {
        a = findRoot(a);
        b = findRoot(b);
        if (a == b) return false;
        if (sizes[a] < sizes[b]) {
            int t = a;
            a = b;
            b = t;
        }
        parent[b] = a;
        sizes[a] += sizes[b];
        return true;
    }

    public static void main(String[] args) throws IOException {
        long h = Long.parseLong(next());
        long w = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[][] ops = new long[(int) q][2];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = Long.parseLong(next());
            }
        }

        int rowsCount = (int) h, colsCount = (int) w;
        int cells = rowsCount * colsCount;
        parent = new int[cells];
        sizes = new int[cells];
        for (int v = 0; v < cells; v++) {
            parent[v] = v;
            sizes[v] = 1;
        }
        boolean[] land = new boolean[cells];
        long count = 0;
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < ops.length; i++) {
            int r = (int) ops[i][0] - 1, c = (int) ops[i][1] - 1;
            int p = r * colsCount + c;
            if (!land[p]) {
                land[p] = true;
                count++;
                for (int d = 0; d < 4; d++) {
                    int a = r + dr[d], b = c + dc[d];
                    if (a >= 0 && a < rowsCount && b >= 0 && b < colsCount && land[a * colsCount + b]) {
                        if (unite(p, a * colsCount + b)) count--;
                    }
                }
            }
            out.append(i > 0 ? " " : "").append(count);
        }
        System.out.println(out);
    }
}
